"""首批两题只读独立复算，不调用参考实现。"""
import hashlib,html,json,random,re
from pathlib import Path

def convolution(text):
 v=list(map(int,text.split()));m,n,p,q=v[:4];matrix=v[4:4+m*n];kernel=v[4+m*n:];assert len(kernel)==p*q
 bound=p*q*max(map(abs,matrix),default=0)*max(map(abs,kernel),default=0);width=max(1,(bound.bit_length()+7)//8)
 def packed(values,negative):return int.from_bytes(b''.join((max(0,-value) if negative else max(0,value)).to_bytes(width,'little') for value in values),'little')
 reverse=[0]*((p-1)*n+q)
 for i in range(p):
  for j in range(q):reverse[(p-1-i)*n+q-1-j]=kernel[i*q+j]
 a,b=packed(matrix,False),packed(matrix,True);c,d=packed(reverse,False),packed(reverse,True)
 blobs=[value.to_bytes((m+p)*n*width,'little') for value in (a*c,b*d,a*d,b*c)]
 def coefficient(index):
  start=index*width;parts=[int.from_bytes(blob[start:start+width],'little') for blob in blobs];return parts[0]+parts[1]-parts[2]-parts[3]
 return '\n'.join(' '.join(str(coefficient((r+p-1)*n+s+q-1)) for s in range(n-q+1)) for r in range(m-p+1))
def laplacian(text):
 from collections import Counter
 v=list(map(int,text.split()));n,m=v[:2];assert len(v)==2+2*m
 counts=Counter()
 for u,w in zip(v[2::2],v[3::2]):
  if u!=w:counts[u,w]+=1;counts[w,u]+=1
 return '\n'.join(' '.join(str(sum(counts[u,w] for w in range(n)) if u==z else -counts[u,z]) for z in range(n)) for u in range(n))
def sample(number,label):
 text=Path(f'data/openjudge/pages/practice__{number}.html').read_text();match=re.search(r'<dt>\s*'+label+r'\s*</dt>\s*<dd>\s*<pre[^>]*>(.*?)</pre>',text,re.S);assert match,(number,label);return html.unescape(match[1])
rng=random.Random(19942)
for _ in range(200):
 m,n=rng.randint(1,7),rng.randint(1,7);p,q=rng.randint(1,m),rng.randint(1,n);a=[rng.randint(-20,20) for _ in range(m*n)];b=[rng.randint(-20,20) for _ in range(p*q)];text=f'{m} {n} {p} {q}\n'+' '.join(map(str,a+b));brute=[sum(a[(r+i)*n+s+j]*b[i*q+j] for i in range(p) for j in range(q)) for r in range(m-p+1) for s in range(n-q+1)];assert list(map(int,convolution(text).split()))==brute
for _ in range(200):
 n=rng.randint(1,10);edges=[(rng.randrange(n),rng.randrange(n)) for _ in range(rng.randrange(25))];incidence=[[int(u==vertex)-int(w==vertex) for u,w in edges] for vertex in range(n)];expected=[sum(a*b for a,b in zip(incidence[i],incidence[j])) for i in range(n) for j in range(n)];text=f'{n} {len(edges)}\n'+'\n'.join(f'{u} {w}' for u,w in edges);assert list(map(int,laplacian(text).split()))==expected
p=Path('collab/gmyhf-pending-triage.json');report=json.loads(p.read_text());entries={e['global_number']:e for e in report['entries']};checks=[]
for n,solver,method in ((19942,convolution,'正负系数分离的整数打包多项式乘法，反转核后提取卷积系数'),(19943,laplacian,'按有向边计数先建邻接权重，再以行和构造度数；随机图以关联矩阵BB^T复核')):
 samples=re.findall(r'Sample\d+ Input:\s*(.*?)Sample\d+ Output:\s*(.*?)(?=Sample\d+ Input:|\Z)',sample(n,'样例输入')+'\n'+sample(n,'样例输出'),re.S) if n==19942 else [(sample(n,'样例输入'),sample(n,'样例输出'))]
 assert samples
 for given,expected in samples:assert solver(given).split()==expected.split()
 rows=[]
 for record in entries[n]['read_only_comparison']['records']:
  inf=Path('data/openjudge/tests/admin_download')/str(n)/record['input'];outf=inf.with_name(record['output']);assert hashlib.sha256(inf.read_bytes()).hexdigest()==record['input_sha256'];assert hashlib.sha256(outf.read_bytes()).hexdigest()==record['output_sha256'];matches=solver(inf.read_text(encoding='utf-8-sig')).split()==outf.read_text(encoding='utf-8-sig').split();assert matches,(n,record['input']);rows.append({**record,'matches':matches})
 checks.append({'global_number':n,'method':method,'official_sample_passed':True,'official_samples':len(samples),'random_small_checks':200,'cases':len(rows),'files':rows,'scope':'只读独立答案复算通过；尚未接入，仍需保留输入契约的接入设计及真实判题复核。'})
 print(n,len(rows),'组独立答案一致')
report['candidate_answer_checks']={'procedure_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'entries':checks};p.write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
